    /// Indexed by Names::displayLanguageIndex(); see Names/NameLanguage.h.
    static const char* const* const ITEM_NAMES_BY_LANGUAGE[] = {
        ITEM_NAMES_JA,
        ITEM_NAMES_EN,
        ITEM_NAMES_FR,
        ITEM_NAMES_IT,
        ITEM_NAMES_DE,
        ITEM_NAMES_ES,
        ITEM_NAMES_KO,
        ITEM_NAMES_ZH_HANS,
        ITEM_NAMES_ZH_HANT,
    };
    static_assert(sizeof(ITEM_NAMES_BY_LANGUAGE) / sizeof(ITEM_NAMES_BY_LANGUAGE[0]) == LANGUAGE_COUNT, "ITEM_NAMES_BY_LANGUAGE must carry one table per language");

    const char *getItemName(uint16_t itemId)
    {
        // Out of range OR a genuinely-unnamed slot (a handful of ids are blank even in
        // PKHeX) -> a visible marker rather than an empty string, so a data gap never
        // renders as a blank tile (the exact failure that made Z-A key items show up empty).
        constexpr size_t count = sizeof(ITEM_NAMES_EN) / sizeof(ITEM_NAMES_EN[0]);
        const char *const *table = ITEM_NAMES_BY_LANGUAGE[displayLanguageIndex()];
        if (itemId >= count || table[itemId][0] == '\0')
            return "???";
        return table[itemId];
    }

    size_t getItemCount() { return 2685; }

